18	export interface UseApprovalModeIndicatorArgs {
19	  config: Config;
20	  addItem?: (item: HistoryItemWithoutId, timestamp: number) => void;
21	  onApprovalModeChange?: (mode: ApprovalMode) => void;
22	  isActive?: boolean;
23	  allowPlanMode?: boolean;
24	}
