26	export function useApprovalModeIndicator({
27	  config,
28	  addItem,
29	  onApprovalModeChange,
30	  isActive = true,
31	  allowPlanMode = false,
32	}: UseApprovalModeIndicatorArgs): ApprovalMode {
33	  const currentConfigValue = config.getApprovalMode();
34	  const [showApprovalMode, setApprovalMode] = useState(currentConfigValue);
35	
36	  useEffect(() => {
37	    setApprovalMode(currentConfigValue);
38	  }, [currentConfigValue]);
39	
40	  useKeypress(
41	    (key) => {
42	      let nextApprovalMode: ApprovalMode | undefined;
43	
44	      if (keyMatchers[Command.TOGGLE_YOLO](key)) {
45	        if (
46	          config.isYoloModeDisabled() &&
47	          config.getApprovalMode() !== ApprovalMode.YOLO
48	        ) {
49	          if (addItem) {
50	            let text =
51	              'You cannot enter YOLO mode since it is disabled in your settings.';
52	            const adminSettings = config.getRemoteAdminSettings();
53	            const hasSettings =
54	              adminSettings && Object.keys(adminSettings).length > 0;
55	            if (hasSettings && !adminSettings.strictModeDisabled) {
56	              text = getAdminErrorMessage('YOLO mode', config);
57	            }
58	
59	            addItem(
60	              {
61	                type: MessageType.WARNING,
62	                text,
63	              },
64	              Date.now(),
65	            );
66	          }
67	          return;
68	        }
69	        nextApprovalMode =
70	          config.getApprovalMode() === ApprovalMode.YOLO
71	            ? ApprovalMode.DEFAULT
72	            : ApprovalMode.YOLO;
73	      } else if (keyMatchers[Command.CYCLE_APPROVAL_MODE](key)) {
74	        const currentMode = config.getApprovalMode();
75	        switch (currentMode) {
76	          case ApprovalMode.DEFAULT:
77	            nextApprovalMode = ApprovalMode.AUTO_EDIT;
78	            break;
79	          case ApprovalMode.AUTO_EDIT:
80	            nextApprovalMode = allowPlanMode
81	              ? ApprovalMode.PLAN
82	              : ApprovalMode.DEFAULT;
83	            break;
84	          case ApprovalMode.PLAN:
85	            nextApprovalMode = ApprovalMode.DEFAULT;
86	            break;
