m(\n              {\n                type: MessageType.WARNING,\n                text,\n              },\n              Date.now(),\n            );\n          }\n          return;\n        }\n        nextApprovalMode =\n          config.getApprovalMode() === ApprovalMode.YOLO\n            ? ApprovalMode.DEFAULT\n            : ApprovalMode.YOLO;\n      } else if (keyMatchers[Command.CYCLE_APPROVAL_MODE](key)) {\n        const currentMode = config.getApprovalMode();\n        switch (currentMode) {\n          case ApprovalMode.DEFAULT:\n            nextApprovalMode = ApprovalMode.AUTO_EDIT;\n            break;\n          case ApprovalMode.AUTO_EDIT:\n            nextApprovalMode = allowPlanMode\n              ? ApprovalMode.PLAN\n              : ApprovalMode.DEFAULT;\n            break;\n          case ApprovalMode.PLAN:\n            nextApprovalMode = ApprovalMode.DEFAULT;\n            break;\n          case ApprovalMode.YOLO:\n            nextApprovalMode = ApprovalMode.AUTO_EDIT;\n            break;\n          default:\n        }\n      }\n\n      if (nextApprovalMode) {\n        try {\n          config.setApprovalMode(nextApprovalMode);\n          // Update local state immediately for responsiveness\n          setApprovalMode(nextApprovalMode);\n\n          // Notify the central handler about the approval mode change\n          onApprovalModeChange?.(nextApprovalMode);\n        } catch (e) {\n          if (addItem) {\n            addItem(\n              {\n                type: MessageType.INFO,\n                // eslint-disable-next-line @typescript-eslint/no-unsafe-type-assertion\n                text: (e as Error).message,\n              },\n              Date.now(),\n            );\n          }\n        }\n      }\n    },\n    { isActive },\n  );\n\n  return showApprovalMode;\n}\n", "numLines": 121, "startLine": 1, "totalLines": 121}}

