import { ApprovalMode } from '../policy/types.js';

/**
 * Returns a human-readable description for an approval mode.
 */
export function getApprovalModeDescription(mode: ApprovalMode): string {
  switch (mode) {
    case ApprovalMode.DEFAULT:
      return 'Default mode (edits will require confirmation)';
    case ApprovalMode.AUTO_EDIT:
      return 'Auto-Edit mode (edits will be applied automatically)';
    case ApprovalMode.PLAN:
      return 'Plan mode (read-only planning)';
    case ApprovalMode.YOLO:
      return 'YOLO mode (all tool calls auto-approved)';
    default:
      return getApprovalModeDescription(ApprovalMode.DEFAULT);
  }
}

/**
 * Composes a message describing the exit from Plan Mode, intended to be added
 * to the conversation history so the model is aware of the mode change.
 *
 * @param mode The approval mode being switched to.
 * @param manual Whether the user manually exited Plan Mode (as opposed to the
 *   plan being approved). Defaults to `false`.
 */
export function getPlanModeExitMessage(
  mode: ApprovalMode,
  manual = false,
): string {
  const description = getApprovalModeDescription(mode);
  return manual
    ? `User has manually exited Plan Mode. Switching to ${description}.`
    : `Plan approved. Switching to ${description}.`;
}
